import{h as t,b as r,c as s,g as p}from"./chunks/framework.C4Db0Jy7.js";const h=JSON.parse('{"title":"博客已迁移至VitePress","description":"","frontmatter":{"title":"博客已迁移至VitePress","date":"2026-07-04T00:00:00.000Z","tag":["前端","Vue"]},"headers":[],"relativePath":"posts/blog-vitepress-migration/index.md","filePath":"posts/blog-vitepress-migration/index.md"}'),m={name:"posts/blog-vitepress-migration/index.md"};function i(a,e,o,n,g,l){return r(),s("div",null,[...e[0]||(e[0]=[p('<p>忙活了两周，总算迁移过来了！</p><hr><p>去年的这个时候，我使用<a href="https://v2.vuepress.vuejs.org/" target="_blank" rel="noreferrer">vuepress-next</a>搭建了这个博客</p><p>原博客的主题基于<a href="https://theme-hope.vuejs.press/" target="_blank" rel="noreferrer">vuepress-theme-hope</a>，虽然提供了开箱即用的博客功能，但样式还是不太符合我的口味</p><p><img src="/posts/blog-vitepress-migration/01.png" alt="原主题"></p><p>我本想在原主题上进一步修改，但我之前对前端一窍不通，让AI大改了一通反而越改越奇怪，自己也看不懂AI拉的CSS，于是寻思着能不能找个时机换个主题或者彻底重写一通...</p><p>后面发现VuePress的正统继承者<a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a>，尽管它的默认主题更像是一个文档而非博客网站，而现有的第三方主题大多基于默认主题，也不太能满足要求</p><p>但好在VitePress提供了完全自定义主题的能力，那我们只要用他的SSG功能，从零开始构建主题就行</p><hr><p>还是想让自己的博客更有特色一点（可能也有一点情怀在？），最后用了Metro的设计风格</p><p>这是主页的初稿：</p><p><img src="/posts/blog-vitepress-migration/02.png" alt="主页初稿"></p><p>后来寻思主页只展示文章还是太单调了，而且磁贴部分加的有些生硬，就仿照Windows 8的官网改成了现在这个样子</p><p>最终效果如下：</p><p><img src="/posts/blog-vitepress-migration/03.png" alt="修改后"></p><p><img src="/posts/blog-vitepress-migration/04.png" alt="文章页面"></p><p>现在的主题还是有点耦合，之后可能会找个时间，把主题配置文件啥的拆出来单独发布（当然代码已经在<a href="https://github.com/zxbmmmmmmmmm/zxbmmmmmmmmm.github.io" target="_blank" rel="noreferrer">zxbmmmmmmmmm/zxbmmmmmmmmm.github.io</a>上了）</p>',17)])])}const b=t(m,[["render",i]]);export{h as __pageData,b as default};
